      path: c2.path,
      line: c2.line,
      side: c2.side,
      ...c2.start_line !== void 0 ? { start_line: c2.start_line } : {},
      ...c2.start_side !== void 0 ? { start_side: c2.start_side } : {},
      body: `[${c2.category} / confidence ${c2.confidence}]

${c2.body}`
